dashboard.definition:
{
  "title": "AP stability",
  "description": "Access point reboots derived from uptime, reboot reasons and rates by model and firmware.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "tr",
        "defaultValue": "-24h,now"
      }
    },
    "input_site": {
      "type": "input.text",
      "title": "Site (wildcard)",
      "options": {
        "token": "site",
        "defaultValue": "*"
      }
    }
  },
  "dataSources": {
    "ds_same": {
      "type": "ds.search",
      "name": "Reboots same firmware",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\" status=ONLINE uptimeInMillis>0\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| sort 0 serialNumber _time\n| streamstats current=f last(uptimeInMillis) as prev_up last(firmwareVersion) as prev_fw last(clientCount) as prev_clients by serialNumber\n| eval reboot=if(isnotnull(prev_up) AND uptimeInMillis<prev_up-60000,1,0)\n| eval reboot_type=case(reboot=0,null(),prev_fw=firmwareVersion,\"Same firmware\",true(),\"After firmware change\")\n| eval reboot_time=_time-uptimeInMillis/1000\n| stats count(eval(reboot_type=\"Same firmware\")) as reboots"
      }
    },
    "ds_aps": {
      "type": "ds.search",
      "name": "APs with reboots",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\" status=ONLINE uptimeInMillis>0\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| sort 0 serialNumber _time\n| streamstats current=f last(uptimeInMillis) as prev_up last(firmwareVersion) as prev_fw last(clientCount) as prev_clients by serialNumber\n| eval reboot=if(isnotnull(prev_up) AND uptimeInMillis<prev_up-60000,1,0)\n| eval reboot_type=case(reboot=0,null(),prev_fw=firmwareVersion,\"Same firmware\",true(),\"After firmware change\")\n| eval reboot_time=_time-uptimeInMillis/1000\n| where reboot_type=\"Same firmware\" | stats dc(serialNumber) as aps"
      }
    },
    "ds_fw": {
      "type": "ds.search",
      "name": "Reboots after firmware change",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\" status=ONLINE uptimeInMillis>0\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| sort 0 serialNumber _time\n| streamstats current=f last(uptimeInMillis) as prev_up last(firmwareVersion) as prev_fw last(clientCount) as prev_clients by serialNumber\n| eval reboot=if(isnotnull(prev_up) AND uptimeInMillis<prev_up-60000,1,0)\n| eval reboot_type=case(reboot=0,null(),prev_fw=firmwareVersion,\"Same firmware\",true(),\"After firmware change\")\n| eval reboot_time=_time-uptimeInMillis/1000\n| stats count(eval(reboot_type=\"After firmware change\")) as reboots"
      }
    },
    "ds_time": {
      "type": "ds.search",
      "name": "Reboots over time",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\" status=ONLINE uptimeInMillis>0\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| sort 0 serialNumber _time\n| streamstats current=f last(uptimeInMillis) as prev_up last(firmwareVersion) as prev_fw last(clientCount) as prev_clients by serialNumber\n| eval reboot=if(isnotnull(prev_up) AND uptimeInMillis<prev_up-60000,1,0)\n| eval reboot_type=case(reboot=0,null(),prev_fw=firmwareVersion,\"Same firmware\",true(),\"After firmware change\")\n| eval reboot_time=_time-uptimeInMillis/1000\n| where reboot=1\n| timechart minspan=1h count by reboot_type"
      }
    },
    "ds_cohort": {
      "type": "ds.search",
      "name": "Reboots by model and firmware",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\" status=ONLINE uptimeInMillis>0\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| sort 0 serialNumber _time\n| streamstats current=f last(uptimeInMillis) as prev_up last(firmwareVersion) as prev_fw last(clientCount) as prev_clients by serialNumber\n| eval reboot=if(isnotnull(prev_up) AND uptimeInMillis<prev_up-60000,1,0)\n| eval reboot_type=case(reboot=0,null(),prev_fw=firmwareVersion,\"Same firmware\",true(),\"After firmware change\")\n| eval reboot_time=_time-uptimeInMillis/1000\n| stats dc(serialNumber) as APs count(eval(reboot_type=\"Same firmware\")) as reboots by model firmwareVersion\n| eval reboots_per_100_APs=round(100*reboots/APs,1)\n| sort - reboots_per_100_APs\n| rename model as Model, firmwareVersion as Firmware, reboots as \"Reboots (same firmware)\", reboots_per_100_APs as \"Per 100 APs\""
      }
    },
    "ds_top": {
      "type": "ds.search",
      "name": "Top rebooting APs",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\" status=ONLINE uptimeInMillis>0\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| sort 0 serialNumber _time\n| streamstats current=f last(uptimeInMillis) as prev_up last(firmwareVersion) as prev_fw last(clientCount) as prev_clients by serialNumber\n| eval reboot=if(isnotnull(prev_up) AND uptimeInMillis<prev_up-60000,1,0)\n| eval reboot_type=case(reboot=0,null(),prev_fw=firmwareVersion,\"Same firmware\",true(),\"After firmware change\")\n| eval reboot_time=_time-uptimeInMillis/1000\n| where reboot_type=\"Same firmware\"\n| stats count as Reboots latest(reboot_time) as lr latest(deviceName) as AP latest(model) as Model latest(siteName) as Site latest(firmwareVersion) as Firmware max(prev_clients) as clients_before by serialNumber\n| eval \"Last reboot\"=strftime(lr,\"%Y-%m-%d %H:%M\")\n| table serialNumber AP Model Site Firmware Reboots \"Last reboot\" clients_before\n| sort - Reboots\n| rename clients_before as \"Clients before\""
      }
    },
    "ds_reason": {
      "type": "ds.search",
      "name": "Last reboot reason",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\"\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(lastRebootReason) as reason by serialNumber\n| eval reason=if(isnull(reason) OR reason=\"\" OR reason=\"null\",\"(not reported)\",reason)\n| stats count by reason\n| sort - count"
      }
    },
    "ds_crash": {
      "type": "ds.search",
      "name": "Crash-like reasons",
      "options": {
        "query": "`aruba_central_index` sourcetype=\"aruba:central:ap\"\n| eval siteName=coalesce(siteName,\"(no site)\") | search siteName=\"$site$\"\n| stats latest(lastRebootReason) as reason latest(deviceName) as AP latest(model) as Model latest(siteName) as Site latest(firmwareVersion) as Firmware latest(uptimeInMillis) as up by serialNumber\n| where match(reason,\"(?i)panic|crash|assert|watchdog|fatal|oops\")\n| eval \"Uptime (h)\"=round(up/3600000,1)\n| table serialNumber AP Model Site Firmware reason \"Uptime (h)\"\n| rename reason as \"Last reboot reason\""
      }
    }
  },
  "visualizations": {
    "v_same": {
      "type": "splunk.singlevalue",
      "title": "Reboots on the same firmware",
      "dataSources": {
        "primary": "ds_same"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "v_aps": {
      "type": "splunk.singlevalue",
      "title": "Access points that rebooted",
      "dataSources": {
        "primary": "ds_aps"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "v_fw": {
      "type": "splunk.singlevalue",
      "title": "Reboots after a firmware change",
      "dataSources": {
        "primary": "ds_fw"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "v_time": {
      "type": "splunk.column",
      "title": "Reboots over time",
      "dataSources": {
        "primary": "ds_time"
      },
      "options": {
        "x": "> primary | seriesByName('_time')",
        "legendDisplay": "bottom",
        "y": "> primary | frameBySeriesTypes('number')",
        "stackMode": "stacked"
      }
    },
    "v_cohort": {
      "type": "splunk.table",
      "title": "Reboots by model and firmware",
      "dataSources": {
        "primary": "ds_cohort"
      },
      "options": {
        "count": 8
      }
    },
    "v_top": {
      "type": "splunk.table",
      "title": "Access points with reboots on the same firmware",
      "dataSources": {
        "primary": "ds_top"
      },
      "options": {
        "count": 8
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_central_poc/access_point?form.serial=$row.serialNumber.value$&form.site=*",
            "newTab": false
          }
        }
      ]
    },
    "v_reason": {
      "type": "splunk.bar",
      "title": "Last reboot reason (latest per access point)",
      "dataSources": {
        "primary": "ds_reason"
      },
      "options": {
        "x": "> primary | seriesByName('reason')",
        "legendDisplay": "off",
        "y": "> primary | frameBySeriesNames('count')"
      }
    },
    "v_crash": {
      "type": "splunk.table",
      "title": "Last reboot reason looks like a crash",
      "dataSources": {
        "primary": "ds_crash"
      },
      "options": {
        "count": 8
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/aruba_central_poc/access_point?form.serial=$row.serialNumber.value$&form.site=*",
            "newTab": false
          }
        }
      ]
    },
    "v_note": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Reboots are derived from uptime: a drop of more than one minute between two polls while the access point was online. They are indicators and depend on the poll interval of the Wireless input. A drop together with a new firmware version is counted as *after a firmware change*. `lastRebootReason` is not reported for every access point. A larger time range makes the first search slower.",
        "fontSize": "small"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$tr.earliest$",
            "latest": "$tr.latest$"
          }
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_time",
      "input_site"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1200,
          "height": 1270
        },
        "structure": [
          {
            "item": "v_same",
            "type": "block",
            "position": {
              "x": 0,
              "y": 0,
              "w": 390,
              "h": 150
            }
          },
          {
            "item": "v_aps",
            "type": "block",
            "position": {
              "x": 400,
              "y": 0,
              "w": 390,
              "h": 150
            }
          },
          {
            "item": "v_fw",
            "type": "block",
            "position": {
              "x": 800,
              "y": 0,
              "w": 390,
              "h": 150
            }
          },
          {
            "item": "v_time",
            "type": "block",
            "position": {
              "x": 0,
              "y": 170,
              "w": 1200,
              "h": 280
            }
          },
          {
            "item": "v_cohort",
            "type": "block",
            "position": {
              "x": 0,
              "y": 470,
              "w": 590,
              "h": 330
            }
          },
          {
            "item": "v_top",
            "type": "block",
            "position": {
              "x": 610,
              "y": 470,
              "w": 590,
              "h": 330
            }
          },
          {
            "item": "v_reason",
            "type": "block",
            "position": {
              "x": 0,
              "y": 820,
              "w": 590,
              "h": 300
            }
          },
          {
            "item": "v_crash",
            "type": "block",
            "position": {
              "x": 610,
              "y": 820,
              "w": 590,
              "h": 300
            }
          },
          {
            "item": "v_note",
            "type": "block",
            "position": {
              "x": 0,
              "y": 1140,
              "w": 1200,
              "h": 110
            }
          }
        ]
      }
    },
    "options": {
      "submitButton": false
    },
    "tabs": {
      "items": [
        {
          "layoutId": "layout_1",
          "label": "AP stability"
        }
      ]
    }
  }
}
